// Calculate the distance vector between particles i and j
glm::vec3 r = pj->position - pi->position;
float rLength = glm::length(r);
glm::vec3 rNormalized = r / rLength;

// Calculate the density at particle i
float density = pi->density;

// Calculate the pressure force using the spiky gradient kernel
float pressureForce = -mass * (pi->pressure / (density * density)) * spikyGrad * (h - rLength) / (h * h * h);

// Calculate the viscosity force using the spiky Laplacian kernel
float viscosityForce = viscosity * mass * (pj->velocity - pi->velocity) / density * spikyLap * (h - rLength) / (h * h);

// Accumulate the forces
force += pressureForce * rNormalized + viscosityForce * rNormalized;

